17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Map;
28	import java.util.Objects;
29	
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    private final AddressNormalizer addressNormalizer;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper,
82	                                 AddressNormalizer addressNormalizer) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	        this.addressNormalizer = addressNormalizer;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        String address = addressNormalizer.normalize(owner.getAddress());
121	        if (address.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        owner.setAddress(address);
125	        String telephone = toE164(owner.getTelephone());
126	        if (telephone == null) {
127	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
128	        }
129	        owner.setTelephone(telephone);
130	        LocalDate effectiveDate = owner.getRegistrationDate() != null
131	            ? owner.getRegistrationDate() : LocalDate.now();
132	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
133	        if (isDailyLimitReached(owner.getRegistrationDate())) {
134	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
135	        }
136	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
137	        if (isDuplicate(owner, sharesHousehold)) {
138	            return new ResponseEntity<>(HttpStatus.CONFLICT);
139	        }
140	        if (sharesHousehold) {
141	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
142	        }
143	        if (isCityAtCapacity(owner.getCity())) {
144	            return new ResponseEntity<>(HttpStatus.CONFLICT);
145	        }
146	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
147	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
148	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
149	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
150	        this.clinicService.saveOwner(owner);
151	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
152	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    /**
160	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
161	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
162	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
163	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
164	     */
165	    private String nextCustomerCode(String city, String lastName) {
166	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
167	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
168	        int sequence = (int) this.clinicService.findAllOwners().stream()
169	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
170	            .count() + 1;
171	        return String.format("%s-%s-%04d", city3, last3, sequence);
172	    }
173	
174	    /**
175	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
176	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
177	     * (business-day) registration date of the owner being created, so owners are counted per
178	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
179	     */
180	    private boolean isDailyLimitReached(LocalDate day) {
181	        long count = this.clinicService.findAllOwners().stream()
182	            .filter(existing -> day.equals(existing.getRegistrationDate()))
183	            .count();
184	        return count >= 100;
185	    }
186	
187	    /**
188	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
189	     * more than 80 owners have already been created for the given business day. Counts the owners
190	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
191	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
192	     * warning.
193	     */
194	    private boolean isBulkSignup(LocalDate day) {
195	        long count = this.clinicService.findAllOwners().stream()
196	            .filter(existing -> day.equals(existing.getRegistrationDate()))
197	            .count();
198	        return count > 80;
199	    }
200	
201	    /**
202	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
203	     * advance it to the following Monday; a weekday is returned unchanged.
204	     */
205	    private LocalDate toBusinessDay(LocalDate date) {
206	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
207	            date = date.plusDays(1);
208	        }
209	        return date;
210	    }
211	
212	    /**
213	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
214	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
215	     */
216	    private boolean isCityAtCapacity(String city) {
217	        long count = this.clinicService.findAllOwners().stream()
218	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
219	            .count();
220	        return count >= 50;
221	    }
222	
223	    /**
224	     * The number of existing owners that already share the given firstName and lastName,
225	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
226	     * whitespace runs collapsed). Counted over the owners present before this create.
227	     */
228	    private int namesakeCount(String firstName, String lastName) {
229	        String candidateFirstName = normalizeName(firstName);
230	        String candidateLastName = normalizeName(lastName);
231	        return (int) this.clinicService.findAllOwners().stream()
232	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
233	                && normalizeName(existing.getLastName()).equals(candidateLastName))
234	            .count();
235	    }
236	
237	    /**
238	     * The number of members in this owner's household after this create: the count of existing
239	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
240	     * created. An owner with no household ({@code householdId == null}) is a household of one.
241	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
242	     * does not depend on the order in which household members were created.
243	     */
244	    private int householdSize(String householdId) {
245	        if (householdId == null) {
246	            return 1;
247	        }
248	        long existing = this.clinicService.findAllOwners().stream()
249	            .filter(other -> householdId.equals(other.getHouseholdId()))
250	            .count();
251	        return (int) existing + 1;
252	    }
253	
254	    /**
255	     * The number of national (subscriber) digits required for each known country calling
256	     * code, keyed by the code's digits (without the leading '+'). A number whose country
257	     * code appears here must carry exactly this many digits after the code, e.g. '+61'
258	     * requires 9 national digits and '+1' requires 10.
259	     */
260	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
261	        "1", 10,
262	        "61", 9);
263	
264	    /**
265	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
266	     * cannot form a valid E.164 number.
267	     *
268	     * <p>A leading '+' and country code are kept when present; otherwise country code
269	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
270	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
271	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
272	     * exactly the national-digit count that code requires (see
273	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
274	     */
275	    private String toE164(String telephone) {
276	        if (telephone == null) {
277	            return null;
278	        }
279	        boolean hasCountryCode = telephone.trim().startsWith("+");
280	        String digits = telephone.replaceAll("\\D", "");
281	        String e164;
282	        if (hasCountryCode) {
283	            e164 = digits;
284	        } else {
285	            if (digits.startsWith("0")) {
286	                digits = digits.substring(1);
287	            }
288	            e164 = "61" + digits;
289	        }
290	        if (e164.length() < 8 || e164.length() > 15) {
291	            return null;
292	        }
293	        if (!hasValidNationalLength(e164)) {
294	            return null;
295	        }
296	        return "+" + e164;
297	    }
298	
299	    /**
300	     * Whether the E.164 digit string (no leading '+') carries the national-number length
301	     * required by its country calling code. The longest matching known code wins; a number
302	     * whose country code is not recognised passes this check (its length is governed only by
303	     * the general 8-15 digit bound in {@link #toE164}).
304	     */
305	    private boolean hasValidNationalLength(String e164) {
306	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
307	            .filter(entry -> e164.startsWith(entry.getKey()))
308	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
309	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
310	            .orElse(true);
311	    }
312	
313	    /**
314	     * Whether the candidate owner duplicates an owner that already exists, and so must be
315	     * rejected with {@code 409 Conflict}. An owner is a duplicate when it reuses an existing
316	     * owner's telephone (compared in E.164 form) or email (compared case-insensitively), or —
317	     * unless it is explicitly joining a shared household ({@code sharesHousehold}) — when it
318	     * matches an existing household by lastName and address. Any single match makes the owner a
319	     * duplicate.
320	     */
321	    private boolean isDuplicate(Owner owner, boolean sharesHousehold) {
322	        return isTelephoneInUse(owner.getTelephone())
323	            || isEmailInUse(owner.getEmail())
324	            || (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress()));
325	    }
326	
327	    /**
328	     * Whether any existing owner already holds the given telephone number. Both the
329	     * candidate and each stored number are compared in E.164 form, so the check does not
330	     * depend on how each was originally formatted.
331	     */
332	    private boolean isTelephoneInUse(String telephone) {
333	        return this.clinicService.findAllOwners().stream()
334	            .map(Owner::getTelephone)
335	            .filter(Objects::nonNull)
336	            .map(this::toE164)
337	            .filter(Objects::nonNull)
338	            .anyMatch(telephone::equals);
339	    }
340	
341	    /**
342	     * Whether any existing owner already holds the given email address, compared case-insensitively
343	     * (by lower-casing both the candidate and each stored value). A null or empty candidate email is
344	     * never considered in use, so owners without an email do not collide. When true, the new owner
345	     * must be rejected with {@code 409 Conflict}.
346	     */
347	    private boolean isEmailInUse(String email) {
348	        if (email == null || email.isEmpty()) {
349	            return false;
350	        }
351	        String candidate = email.toLowerCase();
352	        return this.clinicService.findAllOwners().stream()
353	            .map(Owner::getEmail)
354	            .filter(Objects::nonNull)
355	            .map(String::toLowerCase)
356	            .anyMatch(candidate::equals);
357	    }
358	
359	    /**
360	     * Whether any existing owner already shares a household with the candidate, i.e. has both
361	     * the same lastName and the same address. Both fields are compared case-insensitively and
362	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
363	     * trimmed), so the check does not depend on casing or spacing.
364	     */
365	    private boolean isHouseholdInUse(String lastName, String address) {
366	        String candidateLastName = normalizeName(lastName);
367	        String candidateAddress = addressNormalizer.normalize(address);
368	        return this.clinicService.findAllOwners().stream()
369	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
370	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
371	    }
372	
373	    /**
374	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
375	     * to a single space and lower-case. A null value normalizes to the empty string.
376	     */
377	    private String normalizeName(String value) {
378	        if (value == null) {
379	            return "";
380	        }
381	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
382	    }
383	
384	    /**
385	     * A stable shared identifier for the household formed by a given lastName and address.
386	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
387	     * lastName and address, so every owner sharing the same household is assigned the same
388	     * value regardless of the order in which they are created. Formatted as the first 12
389	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
390	     */
391	    private String householdId(String lastName, String address) {
392	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
393	        try {
394	            byte[] digest = MessageDigest.getInstance("SHA-256")
395	                .digest(key.getBytes(StandardCharsets.UTF_8));
396	            StringBuilder sb = new StringBuilder(digest.length * 2);
397	            for (byte b : digest) {
398	                sb.append(String.format("%02x", b));
399	            }
400	            return sb.substring(0, 12).toUpperCase();
401	        }
402	        catch (NoSuchAlgorithmException e) {
403	            throw new IllegalStateException("SHA-256 not available", e);
404	        }
405	    }
406	
407	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
408	    @Override
409	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
410	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
411	        if (currentOwner == null) {
412	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
413	        }
414	        currentOwner.setAddress(ownerFieldsDto.getAddress());
415	        currentOwner.setCity(ownerFieldsDto.getCity());
416	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
417	        currentOwner.setLastName(ownerFieldsDto.getLastName());
418	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
419	        this.clinicService.saveOwner(currentOwner);
420	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
421	    }
422	
423	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
424	    @Transactional
425	    @Override
426	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
427	        Owner owner = this.clinicService.findOwnerById(ownerId);
428	        if (owner == null) {
429	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
430	        }
431	        this.clinicService.deleteOwner(owner);
432	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
433	    }
434	
435	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
436	    @Override
437	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
438	        Owner owner = this.clinicService.findOwnerById(ownerId);
439	        if (owner == null) {
440	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
441	        }
442	        HttpHeaders headers = new HttpHeaders();
443	        Pet pet = petMapper.toPet(petFieldsDto);
444	        owner.setId(ownerId);
445	        pet.setOwner(owner);
446	        pet.getType().setName(null);
447	        this.clinicService.savePet(pet);
448	        PetDto petDto = petMapper.toPetDto(pet);
449	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
450	            .buildAndExpand(pet.getId()).toUri());
451	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
452	    }
453	
454	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
455	    @Override
456	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
457	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
458	        if (currentOwner != null) {
459	            Pet currentPet = this.clinicService.findPetById(petId);
460	            if (currentPet != null) {
461	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
462	                currentPet.setName(petFieldsDto.getName());
463	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
464	                this.clinicService.savePet(currentPet);
465	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
466	            }
467	        }
468	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
469	    }
470	
471	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
472	    @Override
473	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
474	        HttpHeaders headers = new HttpHeaders();
475	        Visit visit = visitMapper.toVisit(visitFieldsDto);
476	        Pet pet = new Pet();
477	        pet.setId(petId);
478	        visit.setPet(pet);
479	        this.clinicService.saveVisit(visit);
480	        VisitDto visitDto = visitMapper.toVisitDto(visit);
481	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
482	            .buildAndExpand(visit.getId()).toUri());
483	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
484	    }
485	
486	
487	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
488	    @Override
489	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
490	        Owner owner = this.clinicService.findOwnerById(ownerId);
491	        if (owner != null) {
492	            Pet pet = owner.getPet(petId);
493	            if (pet != null) {
494	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
495	            }
496	        }
497	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
498	    }
499	}
